<template>
  <div class="container">
    <h3 class="mt-2 mb-2">Product List</h3>
    <table class="table table-striped">
    <thead class="table-primary">
        <tr>
        <th scope="col">#</th>
        <th scope="col">Descriptions</th>
        <th scope="col">Stocks</th>
        <th scope="col">Unit</th>
        <th scope="col">Price</th>
        </tr>
    </thead>
    <tbody v-for="item in vardata.prods" key="item.id">
        <tr>
        <td>{{item.id}}</td>
        <td>{{item.descriptions}}</td>
        <td>{{item.qty}}</td>
        <td>{{item.unit}}</td>
        <td>&#8369;{{formatNumberWithCommaDecimal(item.sellprice)}}</td>
        </tr>
    </tbody>
    </table>

     <nav aria-label="Page navigation example">
        <ul class="pagination">
          <li class="page-item"><a @click="lastPage" class="page-link" href="#">Last</a></li>
          <li class="page-item"><a @click="prevPage" class="page-link" href="#">Previous</a></li>
          <li id="next" class="page-item"><a @click="nextPage" class="page-link" href="#">Next</a></li>
          <li class="page-item"><a @click="firstPage" class="page-link" href="#">First</a></li>
          <li class="page-item page-link text-danger">Page&nbsp;{{vardata.page}} of&nbsp;{{vardata.totpage}}</li>
        </ul>
      </nav>
      <div>TOTAL RECORDS : {{ vardata.totalrecords }}</div>
      <div class="align-middle text-danger" v-if="vardata.listMsg">{{ vardata.listMsg }}</div>

  </div>
</template>
<style scoped>
.disabled-li {
    pointer-events: none; 
    opacity: 0.6;
    cursor: not-allowed;
  }
</style>

<script setup lang="ts">
    import {reactive, onMounted} from 'vue'
    import axios from 'axios';

    const api = axios.create({
        baseURL: "http://127.0.0.1:8000",
        headers: {'Accept': 'application/json',
                'Content-Type': 'application/json'}
    })

    const formatNumberWithCommaDecimal = (number: any) => {
    const formatter = new Intl.NumberFormat('en-US', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
    });
    return formatter.format(number);
    };

    let ln: number = 0;

    export interface Product {
        id: string,
        category: string,
        descriptions: string,
        qty: number,
        unit: string,
        sellprice: number
    }

    interface State {
        prods: Product[]
        page: number
        totpage: number
        totalrecords: number
        listMsg: string
    }

    const vardata = reactive<State>({
    prods: [],
    page: 1,
    totpage: 0,
    totalrecords: 0,
    listMsg: ''
    })

    const fetchProducts = async (pg: any) => {
        await api.get<State>(`/api/listproducts/${pg}`)
            .then((res: any) => {        
                vardata.listMsg = res.data.message;
                vardata.prods = res.data.products;
                vardata.totpage = res.data.totpage;
                vardata.page = res.data.page;
                vardata.totalrecords = res.data.totalrecords;
                window.setTimeout(() => { vardata.listMsg = ''; }, 3000);                
            }, (error: any) => {
                if (error.response) {
                    vardata.listMsg = error.response.data.message;
                } else {
                    vardata.listMsg = error.message;
                }
                window.setTimeout(() => { vardata.listMsg = ''; }, 3000);                
            });
    }

    onMounted(() => {
        vardata.listMsg = 'loading data, please wait..';
        fetchProducts(1);
        vardata.listMsg = '';
    });

    const firstPage = (event: any) => {
        event.preventDefault();
            vardata.page = 1;
            fetchProducts(vardata.page);
            return;
    }

    const nextPage = (event: any) => {        
        event.preventDefault();
        if (vardata.page === vardata.totpage) {
            return;
        } 
            vardata.page += 1;
            fetchProducts(vardata.page);
    }

    const prevPage = (event: any) => {
        event.preventDefault();
        vardata.page -= 1;
        ln = (vardata.page * 5) - 5;
        fetchProducts(vardata.page);
        return;
    }

    const lastPage = (event: any) => {
        event.preventDefault();
        vardata.page = vardata.totpage;
        fetchProducts(vardata.page);
        return;

    }
</script>
